SELECT 
FROM tb_event_cmt c
LEFT JOIN tb_users u ON u.uid = c.uid

	c.eid = #{eid}
	AND c.p_cmt_id IS NULL

		AND c.status = #{status}


ORDER BY c.cmt_id DESC
LIMIT #{pageSize} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM tb_event_cmt

	eid = #{eid}
	AND p_cmt_id IS NULL

		AND status = #{status}

SELECT 
FROM tb_event_cmt c
LEFT JOIN tb_users u ON u.uid = c.uid

	c.p_cmt_id = #{parentCmtId}

		AND c.status = #{status}


ORDER BY c.cmt_id ASC
LIMIT #{pageSize} OFFSET #{firstIndex}

SELECT COUNT(*)
FROM tb_event_cmt

	p_cmt_id = #{parentCmtId}

		AND status = #{status}
